public final class HopRigClientTest implements FabricClientGameTest {
    private static void check(boolean ok,String m){if(!ok)throw new AssertionError(m);}
    private static AvatarRenderState state(Minecraft c){return (AvatarRenderState)c.getEntityRenderDispatcher().getRenderer(c.player).createRenderState(c.player,1);}
    private static PlayerSkin skin(PlayerModelType type){for(int i=0;i<100;i++){var s=DefaultPlayerSkin.get(new UUID(0,i));if(s.model()==type)return s;}throw new AssertionError("Skin fixture");}
    private static void release(ClientGameTestContext c){c.getInput().releaseKey(v->v.keyLeft);c.getInput().releaseKey(v->v.keyRight);c.getInput().releaseKey(v->v.keyDown);c.getInput().releaseKey(WildcraftBindings.DEFEND);c.getInput().releaseKey(WildcraftBindings.DODGE);}
    private static void move(ClientGameTestContext c,String direction){if(direction.equals("left"))c.getInput().holdKey(v->v.keyLeft);else if(direction.equals("right"))c.getInput().holdKey(v->v.keyRight);else c.getInput().holdKey(v->v.keyDown);}
    @Override public void runTest(ClientGameTestContext c){var id=new AtomicInteger();var opts=CombatOptions.get();boolean jump=opts.jumpDodge,hold=opts.hold;int follow=opts.follow;
        try(TestSingleplayerContext w=c.worldBuilder().create()){
            w.getConnection().waitForChunksRender();w.getServer().runCommand("gamemode survival @p");w.getServer().runCommand("time set day");w.getServer().runOnServer(s->{for(int x=-12;x<=12;x++)for(int z=-12;z<=12;z++)s.overworld().setBlockAndUpdate(new BlockPos(x,119,z),Blocks.STONE.defaultBlockState());var p=s.getPlayerList().getPlayers().getFirst();p.teleportTo(.5,120,.5);p.getInventory().clearContent();p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(Items.IRON_SWORD));p.inventoryMenu.broadcastChanges();var m=EntityTypes.HUSK.create(s.overworld(),EntitySpawnReason.COMMAND);m.setPos(.5,120,8);m.setNoAi(true);m.setNoGravity(true);s.overworld().addFreshEntity(m);id.set(m.getId());});c.waitFor(v->v.player.getY()>119&&v.level.getEntity(id.get())!=null&&v.player.getMainHandItem().is(Items.IRON_SWORD));c.getInput().resizeWindow(1280,960);c.runOnClient(v->{opts.jumpDodge=false;opts.hold=false;opts.follow=0;v.player.setYRot(0);v.player.setXRot(0);v.options.guiScale().set(2);v.options.setCameraType(CameraType.THIRD_PERSON_BACK);});c.waitFor(v->ActionInput.tickFrame().gameplay());c.getInput().holdKeyFor(WildcraftBindings.LOCK_TARGET,1);c.waitFor(v->Combat.locked(v.player));
            for(var type:new PlayerModelType[]{PlayerModelType.WIDE,PlayerModelType.SLIM})for(var arm:HumanoidArm.values())for(int mode=0;mode<3;mode++)for(String direction:new String[]{"left","right","back"}){
                release(c);c.waitTicks(16);int equipment=mode;
                w.getServer().runOnServer(s->{var p=s.getPlayerList().getPlayers().getFirst();p.teleportTo(p.level(),.5,120,.5,Set.of(),0,0,true);p.setDeltaMovement(Vec3.ZERO);p.setMainArm(arm);p.setHealth(20);p.setInvulnerableTime(0);p.setItemSlot(EquipmentSlot.CHEST,ItemStack.EMPTY);var sword=new ItemStack(Items.IRON_SWORD);check(FusionItems.attach(sword,new ItemStack(Items.COBBLESTONE),s.registryAccess()),"Actual Fuse fixture");p.setItemInHand(InteractionHand.MAIN_HAND,sword);p.setItemInHand(InteractionHand.OFF_HAND,equipment==0?ItemStack.EMPTY:new ItemStack(Items.SHIELD));p.inventoryMenu.broadcastChanges();PlayerStamina.fill(p);CounterAttackAudit.begin(p);});c.waitFor(v->v.player.getMainArm()==arm&&v.player.onGround()&&v.player.getX()>.4&&v.player.getX()<.6&&v.player.getOffhandItem().isEmpty()==(equipment==0));c.runOnClient(v->{v.player.setYRot(0);v.player.setXRot(0);RigAudit.fixture=skin(type);RigAudit.begin();});c.waitTicks(3);if(mode==2){c.getInput().holdKey(WildcraftBindings.DEFEND);c.waitFor(v->Combat.view(v.player).defending()&&v.player.isUsingItem());}
                move(c,direction);c.getInput().holdKeyFor(WildcraftBindings.DODGE,1);String name="dodge_"+direction+"_"+(mode==0?"empty":"carry")+"_"+(arm==HumanoidArm.RIGHT?"R":"L");c.waitFor(v->MeleeActions.hopping(v.player)&&state(v).getData(CombatRigLayer.FRAME)!=null&&state(v).getData(CombatRigLayer.FRAME).clip().equals(name)&&RigAudit.bodies>0&&RigAudit.hands>0);
                c.getInput().releaseKey(v->v.keyLeft);c.getInput().releaseKey(v->v.keyRight);c.getInput().releaseKey(v->v.keyDown);
                w.getServer().runOnServer(s->{var p=s.getPlayerList().getPlayers().getFirst();check(PlayerStamina.get(p).stamina()==92&&CounterAttackAudit.calls==0,"Real hop pays exactly original eight stamina and no attack");check(!p.isUsingItem()&&!Combat.view(p).defending(),"Native hop releases actual shield defense, source carry cannot invent block");check(p.getMainHandItem().getDamageValue()==0&&p.getMainHandItem().get(FusionContent.DATA).remaining()==32&&p.getOffhandItem().getDamageValue()==0,"Source adds no weapon/shield wear or Fuse consumption");});c.takeScreenshot("hop-rig-real-"+direction+"-"+type+"-"+arm+"-mode"+mode);check(c.computeOnClient(v->RigAudit.texture.equals(RigAudit.fixture.body().texturePath().toString())),"Actual native skin texture reaches GPU");c.waitFor(v->!MeleeActions.hopping(v.player)&&v.player.onGround());c.waitTicks(2);
                w.getServer().runOnServer(s->{var p=s.getPlayerList().getPlayers().getFirst();double dx=p.getX()-.5,dz=p.getZ()-.5;check(direction.equals("left")?dx>.5:direction.equals("right")?dx<-.5:dz<-.5,"Actual travel direction is unchanged by main-hand mirroring");check(Math.hypot(dx,dz)<3.5&&Math.abs(p.getY()-120)<.01,"Original bounded movement/gravity/ground remains, no source root displacement");});if(mode==2){c.waitFor(v->v.player.isUsingItem()&&Combat.view(v.player).defending());c.takeScreenshot("hop-rig-native-defense-resumes-"+direction+"-"+type+"-"+arm);}release(c);
            }
            release(c);c.waitTicks(16);w.getServer().runOnServer(s->{var p=s.getPlayerList().getPlayers().getFirst();p.teleportTo(p.level(),.5,120,.5,Set.of(),0,0,true);p.setDeltaMovement(Vec3.ZERO);p.setMainArm(HumanoidArm.RIGHT);p.setItemInHand(InteractionHand.OFF_HAND,ItemStack.EMPTY);p.inventoryMenu.broadcastChanges();PlayerStamina.fill(p);for(int y=120;y<=123;y++)for(int z=-4;z<=4;z++)s.overworld().setBlockAndUpdate(new BlockPos(1,y,z),Blocks.STONE.defaultBlockState());});c.waitFor(v->v.player.onGround()&&v.player.getOffhandItem().isEmpty()&&v.player.getMainArm()==HumanoidArm.RIGHT);c.runOnClient(v->{RigAudit.fixture=skin(PlayerModelType.WIDE);v.player.setYRot(0);v.player.setXRot(0);});c.waitTicks(3);move(c,"left");c.getInput().holdKeyFor(WildcraftBindings.DODGE,1);c.waitFor(v->MeleeActions.hopping(v.player)&&state(v).getData(CombatRigLayer.FRAME)!=null);c.getInput().releaseKey(v->v.keyLeft);c.takeScreenshot("hop-rig-real-wall-no-source-root-motion");c.waitFor(v->!MeleeActions.hopping(v.player)&&v.player.onGround());check(c.computeOnClient(v->v.player.getBoundingBox().maxX<=1.0001),"Qualified source hop still stops at actual native collision");w.getServer().runOnServer(s->{for(int y=120;y<=123;y++)for(int z=-4;z<=4;z++)s.overworld().setBlockAndUpdate(new BlockPos(1,y,z),Blocks.AIR.defaultBlockState());});
            c.waitTicks(16);move(c,"back");c.getInput().holdKeyFor(WildcraftBindings.DODGE,1);c.waitFor(v->MeleeActions.hopping(v.player)&&state(v).getData(CombatRigLayer.FRAME)!=null);c.getInput().releaseKey(v->v.keyDown);c.setScreen(()->new InventoryScreen(Minecraft.getInstance().player));check(c.computeOnClient(v->state(v).getData(CombatRigLayer.FRAME)==null),"Actual GUI immediately owns source-hop display");c.takeScreenshot("hop-rig-gui-native-owner");c.setScreen(()->null);c.waitFor(v->!MeleeActions.hopping(v.player)&&v.player.onGround());
            c.waitTicks(16);w.getServer().runOnServer(s->{var p=s.getPlayerList().getPlayers().getFirst();p.setHealth(20);p.setInvulnerableTime(0);PlayerStamina.fill(p);});move(c,"back");c.getInput().holdKeyFor(WildcraftBindings.DODGE,1);c.waitFor(v->MeleeActions.hopping(v.player)&&state(v).getData(CombatRigLayer.FRAME)!=null);c.getInput().releaseKey(v->v.keyDown);w.getServer().runOnServer(s->{var p=s.getPlayerList().getPlayers().getFirst();p.hurtServer(s.overworld(),p.damageSources().mobAttack((LivingEntity)s.overworld().getEntity(id.get())),2);check(p.getHealth()<20&&!MeleeActions.hopping(p),"Actual source hop has no invulnerability and damage cancels native phase");});c.waitFor(v->v.player.getHealth()<20&&!MeleeActions.hopping(v.player));check(c.computeOnClient(v->{var f=state(v).getData(CombatRigLayer.FRAME);return f==null||!f.clip().startsWith("dodge_");}),"Actual damage removes hop source ownership; current independent hurt may render");c.takeScreenshot("hop-rig-real-damage-cancel");c.waitFor(v->v.player.onGround());
            c.waitTicks(16);w.getServer().runOnServer(s->{var p=s.getPlayerList().getPlayers().getFirst();p.setItemSlot(EquipmentSlot.CHEST,new ItemStack(Items.IRON_CHESTPLATE));p.inventoryMenu.broadcastChanges();PlayerStamina.fill(p);});c.waitFor(v->v.player.getItemBySlot(EquipmentSlot.CHEST).is(Items.IRON_CHESTPLATE));move(c,"back");c.getInput().holdKeyFor(WildcraftBindings.DODGE,1);c.waitFor(v->MeleeActions.hopping(v.player));c.getInput().releaseKey(v->v.keyDown);check(c.computeOnClient(v->state(v).getData(CombatRigLayer.FRAME)==null),"Actual armor hop retains native armor and existing masks");c.takeScreenshot("hop-rig-native-armor");
            System.out.println("C6L actual X/three directions, wide/slim left/right empty/carry/prior-guard, real motion/ground/eight cost/no attack-wear-Fuse, native shield release/resume, real wall/GUI/damage/no immunity/armor and GPU PASS");
        }finally{release(c);c.runOnClient(v->{RigAudit.enabled=false;RigAudit.fixture=null;opts.jumpDodge=jump;opts.hold=hold;opts.follow=follow;v.options.setCameraType(CameraType.FIRST_PERSON);});}
    }
}
